# PTX source for hinge loss (mean of max(0, 1 - pred * target))
PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry hinge_loss_kernel(
    .param .u64 predictions,
    .param .u64 targets,
    .param .u64 output,
    .param .u32 N
)
{
    //------------------------------
    // registers
    .reg .pred   %p;
    .reg .b32    %tid, %ntid, %i, %offset, %idx;
    .reg .b64    %pred_ptr, %tgt_ptr, %out_ptr, %addr;
    .reg .f16    %p_val, %t_val;
    .reg .f32    %f_pred, %f_tgt, %prod, %tmp, %sum, %val, %N_f;

    //------------------------------
    // load kernel parameters
    ld.param.u64 %pred_ptr, [predictions];
    ld.param.u64 %tgt_ptr , [targets];
    ld.param.u64 %out_ptr , [output];
    ld.param.u32 %i        , [N];          // reuse %i as N temporarily
    mov.u32 %N_f, %i;                     // N (int) -> will convert later

    //------------------------------
    // thread identifiers
    mov.u32 %tid , %tid.x;
    mov.u32 %ntid, %ntid.x;

    //------------------------------
    // per‑thread accumulation (float32)
    mov.f32 %sum, 0f0;

    // i = tid (global index, gridDim.x == 1)
    mov.u32 %i, %tid;

LOOP_START:
    setp.ge.u32 %p, %i, %N_f;          // i >= N ?
    @%p    bra REDUCTION_START;        // exit loop if done

    // address = base + i * sizeof(half) (2 bytes)
    mul.wide.u32 %addr, %i, 2;
    add.u64 %addr, %pred_ptr, %addr;
    ld.global.f16 %p_val, [%addr];
    add.u64 %addr, %tgt_ptr, %addr;
    ld.global.f16 %t_val, [%addr];

    // convert to float32
    cvt.f32.f16 %f_pred, %p_val;
    cvt.f32.f16 %f_tgt , %t_val;

    // prod = pred * target
    mul.f32 %prod, %f_pred, %f_tgt;
    // tmp = 1.0 - prod
    sub.f32 %tmp, 1.0, %prod;
    // val = max(tmp, 0.0)
    max.f32 %val, %tmp, 0.0;
    // accumulate
    add.f32 %sum, %sum, %val;

    // i += ntid
    add.u32 %i, %i, %ntid;
    bra LOOP_START;

REDUCTION_START:
    // shared memory for block reduction (max 1024 threads)
    .shared .align 4 .b32 sdata[1024];

    // store per‑thread sum into shared memory
    st.shared.b32 [sdata+%tid*4], %sum;
    bar.sync 0;

    // binary tree reduction
    mov.u32 %offset, %ntid;
REDUCE_LOOP:
    shr.u32 %offset, %offset, 1;            // offset >>= 1
    setp.eq.u32 %p, %offset, 0;
    @%p    bra END_REDUCTION;

    // if tid < offset then combine
    setp.lt.u32 %p, %tid, %offset;
    @%p {
        // idx = tid + offset
        add.u32 %idx, %tid, %offset;
        // load a = sdata[tid], b = sdata[idx]
        ld.shared.b32 %val, [sdata+%tid*4];
        ld.shared.b32 %tmp, [sdata+%idx*4];
        add.f32 %val, %val, %tmp;
        st.shared.b32 [sdata+%tid*4], %val;
    }
    bar.sync 0;
    bra REDUCE_LOOP;

END_REDUCTION:
    // thread 0 writes the final mean
    setp.ne.u32 %p, %tid, 0;
    @%p    bra KERNEL_EXIT;

    // load total sum from shared[0]
    ld.shared.b32 %val, [sdata];
    // convert N to float32
    cvt.f32.u32 %N_f, %N_f;
    // mean = sum / N
    div.f32 %val, %val, %N_f;
    // cast to half and store
    cvt.f16.f32 %p_val, %val;
    st.global.f16 [%out_ptr], %p_val;

KERNEL_EXIT:
    ret;
}
'''

class ModelNew:
    """
    Drop‑in replacement for the reference PyTorch model.
    Computes the mean hinge loss on FP16 tensors using a custom PTX kernel.
    """
    def __init__(self):
        # Load the PTX module (ptx_harness provides ptx_load)
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, predictions: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
        """
        predictions: (batch_size,) float16 tensor
        targets:     (batch_size,) float16 tensor with values -1 or +1
        Returns: scalar tensor (float16) containing the mean hinge loss.
        """
        assert predictions.is_cuda and targets.is_cuda
        assert predictions.dtype == torch.float16 and targets.dtype == torch.float16
        out = torch.empty((), dtype=torch.float16, device=predictions.device)

        N = predictions.numel()
        # Launch configuration: one block (grid=1) with 1024 threads (max for A100)
        grid = (1, 1, 1)
        block = (1024, 1, 1)

        # Arguments: raw device pointers and element count (uint32)
        args = [
            predictions.data_ptr(),
            targets.data_ptr(),
            out.data_ptr(),
            N
        ]

        # ptx_harness provides ptx_launch(module, kernel_name, grid, block, args)
        ptx_launch(self.module, "hinge_loss_kernel", grid, block, args)

        return out
